6. Circuit breaker implementation for graceful failure handling

Recommended implementation using Fastify 4.22+ with its schema validation capabilities and the @fastify/circuit-breaker plugin:

```typescript
import fastify from 'fastify';
import fastifyCircuitBreaker from '@fastify/circuit-breaker';
import { UepSchemaRegistry } from './uep-schema-registry';

export function createUepValidationMiddleware(options) {
  const app = fastify();
  const schemaRegistry = new UepSchemaRegistry(options.registryUrl);

  app.register(fastifyCircuitBreaker, {
    threshold: 5,
    timeout: 30000,
    resetTimeout: 30000
  });

  app.addHook('preValidation', async (request, reply) => {
    const schema = await schemaRegistry.getSchema(request.routeConfig.uepCapability);
    const validation = app.validateSchema(schema, request.body);
    if (!validation.valid) {
      request.log.error({ validation }, 'UEP protocol violation');
      reply.code(400).send({ error: 'UEP protocol violation', details: validation.errors });
      return reply;
    }
  });

  return app;
}
```

