```typescript
import { UepTestClient } from './uep-test-client';

describe('Parameter Flow Agent UEP Compliance', () => {
  let uepClient: UepTestClient;

  beforeAll(async () => {
    uepClient = new UepTestClient({
      registryUrl: 'http://uep-registry:8080',
      targetAgent: 'parameter-flow-agent'
    });
    await uepClient.connect();
  });

  test('should comply with map-parameters capability schema', async () => {
    const result = await uepClient.validateCapability('map-parameters');
    expect(result.valid).toBe(true);
    expect(result.violations).toHaveLength(0);
  });

  test('should handle protocol violations correctly', async () => {
    const response = await uepClient.sendInvalidRequest('map-parameters', {
      invalidField: 'should be rejected'
    });
    expect(response.status).toBe(400);
    expect(response.body.error).toContain('UEP protocol violation');
  });

  afterAll(async () => {
    await uepClient.disconnect();
  });
});
```

