Recommended implementation using content negotiation with custom media types:

```typescript
class UepVersionNegotiator {
  private supportedVersions: Map<string, ProtocolHandler>;

  constructor() {
    this.supportedVersions = new Map();
    // Register handlers for different protocol versions
    this.supportedVersions.set('1.0', new UepV1Handler());
    this.supportedVersions.set('1.1', new UepV1_1Handler());
    this.supportedVersions.set('2.0', new UepV2Handler());
  }

  negotiateVersion(acceptHeader: string): ProtocolHandler {
    // Parse Accept header: application/vnd.uep.v1+json, application/vnd.uep.v2+json;q=0.9
    const versions = this.parseAcceptHeader(acceptHeader);

    // Find highest acceptable version that we support
    for (const version of versions) {
      if (this.supportedVersions.has(version)) {
        return this.supportedVersions.get(version);
      }
    }

    // Fall back to latest version we support
    return this.supportedVersions.get('2.0');
  }

  private parseAcceptHeader(header: string): string[] {
    // Implementation of Accept header parsing with quality values
    // Returns ordered list of acceptable versions from highest to lowest priority
  }
}
```

